(function(E){ const x = E["int-m2"] = E["int-m2"] || {units:{}}; x.units["int-5"] = {"grammar":{"id":"c-int-5-g","level":"B1","course":"interview","unit":"int-5","title":"Background and events: past continuous and past simple","titleTr":"Arka plan ve olaylar: past continuous ve past simple","titleFa":"زمینه و اتفاق: گذشته‌ی استمراری و گذشته‌ی ساده","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Background: was / were + -ing","I was preparing the report..."],["The event: past simple","...when the system crashed."],["Your steps, one by one: past simple","I called IT and phoned each client."],["while + background","While I was waiting, I checked the numbers."]]},"wrong":"I prepared the report when the system was crashing.","right":"I was preparing the report when the system crashed.","blank":{"sentence":"While the IT team ___ the system, I phoned the first client.","word":"was repairing","distractors":["repairs","has repaired"]},"wrong2":"Then I was calling the client and I was explaining the delay.","right2":"Then I called the client and explained the delay.","blank2":{"sentence":"I was serving a customer when the system suddenly ___.","word":"crashed","distractors":["was crashing","crashes"]},"expParts":{"rule":[{"en":"Background in progress: was / were + -ing.","tr":"Süren arka plan: was / were + -ing.","fa":"برای زمینه‌ای که در جریان بود was یا were را با فعل ing می‌آوری.","ex":"I was preparing the report..."},{"en":"The event that interrupts: when + past simple.","tr":"Araya giren olay: when + past simple.","fa":"اتفاقی که وسط کار پیش آمد با when و گذشته‌ی ساده می‌آید.","ex":"...when the system crashed."},{"en":"Your actions, step by step: past simple.","tr":"Yaptıkların, adım adım: past simple.","fa":"کارهایی را که قدم‌به‌قدم کردی با گذشته‌ی ساده بگو.","ex":"I called IT and phoned each client."}],"test":{"en":"Was it already happening? Use -ing. Did it happen and finish? Use the past simple.","tr":"Zaten oluyor muydu? -ing kullan. Olup bitti mi? Past simple kullan.","fa":"از قبل در جریان بود؟ ‎-ing بیاور. اتفاق افتاد و تمام شد؟ گذشته‌ی ساده بیاور."},"contrast":{"en":"Turkish '-iyordum / -dım' and Persian 'داشتم می‌رفتم / رفتم' make the same split, so the idea is familiar. The trap is the English form: was + -ing, not 'I was drive'.","tr":"Türkçedeki '-iyordum / -dım' ayrımı aynıdır, yani fikir tanıdık. Tuzak İngilizcedeki biçimdedir: was + -ing; 'I was drive' değil.","fa":"تمایز «داشتم می‌رفتم / رفتم» در فارسی هم هست، پس فکرش آشناست. تله در شکل فعل انگلیسی است: was + ‎-ing، نه «I was drive»."}},"errorWatch":[{"find":["i was drive","i was call","i was work","i was wait","i was talk","i was check","we was","they was"],"fix":{"en":"Past continuous = was / were + -ing: 'I was working', 'they were waiting'.","tr":"Past continuous = was / were + -ing: 'I was working', 'they were waiting'.","fa":"گذشته‌ی استمراری = was / were + ‎-ing: «I was driving»، «they were waiting»."}},{"find":["then i was calling","then i was asking","then i was phoning","then i was explaining"],"fix":{"en":"Steps that finished take the past simple: 'Then I called the client and explained the delay.'","tr":"Biten adımlar past simple alır: 'Then I called the client and explained the delay.'","fa":"قدم‌هایی که تمام شدند گذشته‌ی ساده می‌گیرند: «Then I called the client and explained the delay.‎»"}}]},"b2":{"id":"c-int-5-b2","level":"B2","track":"B2","course":"interview","unit":"int-5","title":"What happened first: the past perfect","titleTr":"Önce ne oldu: past perfect","titleFa":"اول چه اتفاقی افتاد: ماضی بعید","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Earlier action: had + past participle","I had already saved the file."],["Later action: past simple","...by the time my manager called back."],["Question","What had you tried before you asked for help?"]]},"wrong":"By the time the client called, I have already sent the new date.","right":"By the time the client called, I had already sent the new date.","blank":{"sentence":"By the time the new parts arrived, the team ___ all the boxes.","word":"had packed","distractors":["have packed","packs"]},"wrong2":"I had already find a second supplier.","right2":"I had already found a second supplier.","blank2":{"sentence":"The client was calm because I ___ them about the delay an hour earlier.","word":"had told","distractors":["have told","was telling"]},"useIn":{"en":"B2: in your STAR story, add one sentence with had + past participle to show what you had already done.","tr":"B2: STAR hikâyene, zaten ne yapmış olduğunu gösteren had + üçüncü hâlli bir cümle ekle.","fa":"در مسیر B2: به ماجرای STAR خودت جمله‌ای با had و اسم مفعول اضافه کن تا نشان بدهی چه کاری را از قبل کرده بودی."},"exitItem":{"from":"int-5","kind":"blank","prompt":"When the inspector arrived, she ___ every temperature record.","options":["had already checked","has already checked","already checks"],"correct":0},"expParts":{"rule":[{"en":"The earlier of two past actions: had + past participle.","tr":"İki geçmiş eylemden önce olanı: had + üçüncü hâl.","fa":"از میان دو کار گذشته، برای کاری که زودتر بوده had و اسم مفعول می‌آوری.","ex":"I had already saved the file."},{"en":"The later action: past simple.","tr":"Sonraki eylem: past simple.","fa":"کار بعدی را با گذشته‌ی ساده می‌آوری.","ex":"By the time my manager called back..."},{"en":"Use it only when the order matters.","tr":"Bunu sadece sıra önemliyse kullan.","fa":"فقط وقتی ترتیب مهم است از آن استفاده کن.","ex":"I called the clients, then I told my manager."}],"test":{"en":"Two past actions, told out of order? The one that happened first gets had.","tr":"İki geçmiş eylem sırasız mı anlatılıyor? Önce olan had alır.","fa":"دو کار گذشته را به ترتیب زمان تعریف نکرده‌ای؟ آن که اول اتفاق افتاده had می‌گیرد."},"contrast":{"en":"Turkish 'bulmuştum' and Persian 'پیدا کرده بودم' are a real past perfect, so the meaning is familiar. The trap is the form: had + past participle, never the base verb.","tr":"Türkçedeki 'bulmuştum' gerçek bir past perfect'tir; anlam tanıdık. Tuzak biçimdedir: had + üçüncü hâl, asla yalın fiil değil.","fa":"«پیدا کرده بودم» در فارسی واقعاً ماضی بعید است و معنایش آشناست. تله در شکل فعل است: بعد از had اسم مفعول می‌آید، نه شکل ساده‌ی فعل."}},"errorWatch":[{"find":["had already find","had already call","had already send","had already tell","had already check","had find","had send","had tell"],"fix":{"en":"Use had + past participle: 'I had already found a second supplier.'","tr":"had + üçüncü hâl kullan: 'I had already found a second supplier.'","fa":"بعد از had اسم مفعول بیاور: «I had already found a second supplier.‎»"}}]},"vocab":{"id":"c-int-5-v","level":"B1","category":"vocab","course":"interview","unit":"int-5","goals":["career"],"title":{"en":"Telling Your Story","tr":"Hikâyeni Anlatmak","fa":"تعریف کردن ماجرای خودت"},"cards":[{"word":"situation","sentence":"First, describe the situation in one or two sentences.","meaning":{"en":"What was happening, where and when.","tr":"durum.","fa":"موقعیت"}},{"word":"result","sentence":"The result was a happy customer and a new contract.","meaning":{"en":"What happened in the end because of your actions.","tr":"sonuç.","fa":"نتیجه"}},{"word":"handle","sentence":"I handled the complaint myself.","meaning":{"en":"To deal with a problem or a situation.","tr":"ilgilenmek, halletmek.","fa":"رسیدگی کردن؛ از پسِ کاری برآمدن"},"gap":"handled","accept":["handled"]},{"word":"solve","sentence":"I solved the problem in two hours by calling the warehouse.","meaning":{"en":"To find the answer to a problem.","tr":"çözmek.","fa":"حل کردن"},"gap":"solved","accept":["solved"]},{"word":"break down","sentence":"The delivery van broke down on the motorway at night.","meaning":{"en":"To stop working (a machine or a vehicle).","tr":"bozulmak, arıza yapmak.","fa":"خراب شدن؛ از کار افتادن"},"gap":"broke down","accept":["broke down"]},{"word":"take responsibility","sentence":"I took responsibility for the late delivery.","meaning":{"en":"To accept that something is your job or your fault.","tr":"sorumluluk almak.","fa":"مسئولیت را پذیرفتن"},"gap":"took responsibility","accept":["took responsibility"]},{"word":"on my own","sentence":"My manager was away, so I decided on my own.","meaning":{"en":"Without help from other people.","tr":"tek başıma.","fa":"به‌تنهایی؛ خودم"}},{"word":"in the end","sentence":"In the end, every customer got a refund.","meaning":{"en":"Finally, after everything happened.","tr":"sonunda.","fa":"در آخر؛ سرانجام"}},{"word":"challenge","sentence":"The biggest challenge was the time.","meaning":{"en":"Something difficult that tests your skill.","tr":"zorluk.","fa":"چالش"}},{"word":"learn from","sentence":"What did you learn from that experience?","meaning":{"en":"To get knowledge or a lesson from something that happened.","tr":"-den ders çıkarmak, öğrenmek.","fa":"از چیزی درس گرفتن"}}]},"judge":{"id":"c-int-5-j","course":"interview","unit":"int-5","type":"judge","title":{"en":"Is it a story?","tr":"Bu bir hikâye mi?","fa":"این یک ماجراست؟"},"prompt":"Five answers to \"Tell me about a time when you solved a problem\".","parts":["Situation and task, briefly","My own actions (I)","A result"],"instruction":{"en":"Tap what each answer has. The strongest answer has all three.","tr":"Her cevapta ne olduğuna dokun. En güçlü cevapta üçü de vardır.","fa":"روی چیزهایی که هر جواب دارد بزن. قوی‌ترین جواب هر سه را دارد."},"items":[{"by":"Engineer","answer":"We had a big problem last year, and we worked as a great team. We all stayed late, and in the end we fixed it.","present":["A result"],"fix":{"en":"Who did what? The interviewer is hiring you, not your team. Thank them once, then say \"I\": \"I found the faulty part and called the supplier.\"","tr":"Kim ne yaptı? Mülakatçı ekibini değil seni işe alıyor. Ekibine bir kez teşekkür et, sonra \"I\" de: \"I found the faulty part and called the supplier.\"","fa":"چه کسی چه کرد؟ مصاحبه‌کننده می‌خواهد تو را استخدام کند، نه تیمت را. یک بار از تیم تشکر کن و بعد بگو «I»: «I found the faulty part and called the supplier.»"}},{"by":"Receptionist","answer":"Our hotel has 120 rooms, and in summer it is very busy because many tours come from Europe, and the computer system is quite old, and the manager is often away, and there are only three of us on a shift.","present":[],"fix":{"en":"All background, and no action yet. Give the situation in one or two sentences. Most of your answer should be what you did.","tr":"Hepsi arka plan, henüz eylem yok. Durumu bir iki cümleyle ver. Cevabının çoğu senin yaptıkların olmalı.","fa":"همه‌اش زمینه است و هنوز از کار خودت نگفته‌ای. موقعیت را در یکی دو جمله بگو. بیشتر جوابت باید کاری باشد که خودت کردی."}},{"by":"Driver","answer":"Last March I was driving to Izmit with medicine when my van broke down. I called two drivers and phoned each hospital myself.","present":["Situation and task, briefly","My own actions (I)"],"fix":{"en":"A good start, then it stops. Say how it ended: \"Two hospitals got everything on time. One was four hours late, and I told them first.\"","tr":"İyi başlıyor, sonra duruyor. Nasıl bittiğini söyle: \"Two hospitals got everything on time. One was four hours late, and I told them first.\"","fa":"خوب شروع می‌شود، ولی ناتمام می‌ماند. بگو چطور تمام شد: «Two hospitals got everything on time. One was four hours late, and I told them first.»"}},{"by":"AI tool","answer":"In my previous role, I consistently leveraged cross-functional collaboration to drive impactful outcomes and resolve complex challenges.","present":[],"fix":{"en":"No day, no place, no action. The next question will be \"What exactly did you do?\", and this answer has nothing to say. Use one true moment.","tr":"Gün yok, yer yok, eylem yok. Sıradaki soru \"What exactly did you do?\" olur ve bu cevabın söyleyecek bir şeyi yoktur. Gerçek bir anı kullan.","fa":"نه روزی در آن هست، نه جایی و نه کاری. سؤال بعدی «What exactly did you do?» است و این جواب حرفی برای گفتن ندارد. از یک موقعیت واقعی استفاده کن."}},{"by":"Good model","answer":"Last May our payment system crashed during a sale, and I was the tester on duty. I found the faulty update in twenty minutes, told the team and wrote a short message for customers. We lost less than an hour of sales.","present":["Situation and task, briefly","My own actions (I)","A result"],"fix":null}]},"speaking":{"id":"int-5","course":"interview","unit":"int-5","topic":{"en":"Tell me about a time when...","tr":"Bana ... olduğu bir anı anlat","fa":"از دفعه‌ای بگو که..."},"warmup":{"en":"Think of one day at work or at school when something went wrong. Where were you, and when?","tr":"İşte ya da okulda bir şeylerin ters gittiği bir günü düşün. Neredeydin, ne zamandı?","fa":"یک روز در محل کار یا دانشگاه را به یاد بیاور که چیزی خراب شد. کجا بودی و کی بود؟"},"questions":[{"en":"\"Tell me about a time when you solved a problem.\" Situation: where and when, in one or two sentences.","tr":"\"Tell me about a time when you solved a problem.\" Durum: nerede ve ne zaman, bir iki cümleyle.","fa":"«Tell me about a time when you solved a problem.‎» در بخش موقعیت، در یکی دو جمله بگو کجا و چه زمانی بود."},{"en":"Task: what was your job in that moment?","tr":"Görev: o anda senin işin neydi?","fa":"وظیفه: آن لحظه کار تو چه بود؟"},{"en":"Action: what did you do? Say \"I\" at least three times.","tr":"Eylem: ne yaptın? En az üç kez \"I\" de.","fa":"کار: چه کردی؟ دست‌کم سه بار بگو «I»."},{"en":"Result: how did it end? Add a number if you can.","tr":"Sonuç: nasıl bitti? Yapabiliyorsan bir sayı ekle.","fa":"نتیجه: چطور تمام شد؟ اگر می‌توانی یک عدد اضافه کن."}],"expressions":[{"phrase":"Last March, I was ... when...","meaning":{"en":"Sets the scene and the event.","tr":"Arka planı ve olayı verir.","fa":"فضا و اتفاق را مشخص می‌کند."}},{"phrase":"My job was to...","meaning":{"en":"Gives the T in STAR.","tr":"STAR'daki T'yi verir.","fa":"همان T در STAR را می‌گوید."}},{"phrase":"In the end...","meaning":{"en":"Opens the result.","tr":"Sonucu söylemeye başlar.","fa":"نتیجه را شروع می‌کند."}}],"selfCheck":[{"en":"My story had a situation, my task, my actions and a result.","tr":"Hikâyemde bir durum, görevim, eylemlerim ve bir sonuç vardı.","fa":"ماجرایم موقعیت، وظیفه‌ی من، کارهای من و نتیجه داشت."},{"en":"I said \"I\" for my actions, not only \"we\".","tr":"Eylemlerim için sadece \"we\" değil, \"I\" dedim.","fa":"برای کارهای خودم گفتم «I»، نه فقط «we»."},{"en":"I used was / were + -ing for the background and the past simple for the events.","tr":"Arka plan için was / were + -ing, olaylar için past simple kullandım.","fa":"برای زمینه was یا were را با فعل ing و برای اتفاق‌ها گذشته‌ی ساده به کار بردم."},{"en":"The result had a number or a clear outcome.","tr":"Sonuçta bir sayı ya da net bir sonuç vardı.","fa":"نتیجه یک عدد یا پایان روشنی داشت."}],"followups":[{"en":"Tell the same story in 90, then 60, then 45 seconds. Keep all four parts.","tr":"Aynı hikâyeyi 90, sonra 60, sonra 45 saniyede anlat. Dört parçayı da koru.","fa":"همان ماجرا را در ۹۰، بعد ۶۰، بعد ۴۵ ثانیه تعریف کن. هر چهار بخش را نگه دار."},{"en":"Now use the same story for \"Tell me about a time you worked under pressure.\" Change only your first sentence.","tr":"Şimdi aynı hikâyeyi \"Tell me about a time you worked under pressure.\" sorusu için kullan. Yalnızca ilk cümleni değiştir.","fa":"حالا همین ماجرا را برای «Tell me about a time you worked under pressure.» به کار ببر. فقط جمله‌ی اولت را عوض کن."}],"model":"Last May I was working the evening shift when our booking system crashed, with forty guests in the lobby. My job was to keep them calm. I wrote their names on paper, called the IT team and offered everyone coffee. In the end, every guest had a room in thirty minutes, and two of them left us good reviews."},"writing":{"id":"c-int-5-w","course":"interview","unit":"int-5","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"int-final-3","prompt":{"en":"Build your story bank. Write three short STAR stories from your own work or studies, as notes (80-120 words in total): one when something went wrong, one when you helped a person, one when you learned something new. For each: Situation, Task, Action (with \"I\"), Result. Then add \"Also answers:\" with other questions the story fits.","tr":"Hikâye bankanı oluştur. Kendi işinden ya da okulundan üç kısa STAR hikâyesini not olarak yaz (toplam 80-120 kelime): bir şeylerin ters gittiği, birine yardım ettiğin ve yeni bir şey öğrendiğin birer zaman. Her biri için: Situation, Task, Action (\"I\" ile), Result. Sonra \"Also answers:\" yazıp hikâyenin uyduğu başka soruları ekle.","fa":"بانک ماجراهایت را بساز. سه ماجرای کوتاه STAR از کار یا درس خودت را به‌صورت یادداشت بنویس (در مجموع ۸۰ تا ۱۲۰ کلمه): یکی از وقتی که چیزی خراب شد، یکی از وقتی که به کسی کمک کردی و یکی از وقتی که چیز تازه‌ای یاد گرفتی. برای هر کدام: Situation، Task، Action (با «I»)، Result. بعد با «Also answers:» سؤال‌های دیگری را اضافه کن که این ماجرا به آن‌ها هم جواب می‌دهد."},"model":"1. Something went wrong. S: Our payment system crashed during a sale. T: I was the tester on duty. A: I found the faulty update and told the team. R: We lost under an hour of sales. Also answers: pressure, mistakes.\n2. Helping someone. S: A new colleague was failing her first month. T: My manager asked me to help. A: I showed her how to plan tests. R: She passed her probation. Also answers: teamwork.\n3. Learning. S: Our team moved to a new test tool. T: Nobody knew it. A: I took a short course and wrote a guide. R: Everyone used it within a month. Also answers: learning fast.","frame":"1. Something went wrong. S: ___ T: ___ A: I ___ R: ___ Also answers: ___\n2. Helping someone. S: ___ T: ___ A: I ___ R: ___ Also answers: ___\n3. Learning. S: ___ T: ___ A: I ___ R: ___ Also answers: ___","words":[{"word":"I found"},{"word":"I took"},{"word":"Also answers"}],"minWords":80,"minSentences":6,"title":{"en":"Your three best stories","tr":"En iyi üç hikâyen","fa":"سه ماجرای برتر تو"},"rubric":["Task done: three stories, each with situation, task, action and result","Organised: one label per part, in STAR order","Language: past continuous for the background, past simple for the actions; \"I\" for your actions","Tone: factual and modest; the result is true, not made bigger"],"rubricI18n":{"tr":["Görev: üç hikâye; her birinde durum, görev, eylem ve sonuç var","Düzen: her parçaya bir başlık, STAR sırasıyla","Dil: arka plan için past continuous, eylemler için past simple; eylemlerin için \"I\"","Üslup: olgulara dayalı ve alçakgönüllü; sonuç gerçek, abartısız"],"fa":["کامل بودن کار: سه ماجرا، هرکدام با موقعیت، وظیفه، کار و نتیجه","نظم: برای هر بخش یک عنوان، به ترتیب STAR","زبان: گذشته‌ی استمراری برای زمینه، گذشته‌ی ساده برای کارها؛ «I» برای کارهای خودت","لحن: واقعی و فروتنانه؛ نتیجه درست است و بزرگ‌نمایی نشده"]}},"exit":{"id":"c-int-5-x","course":"interview","unit":"int-5","type":"exit","items":[{"from":"int-5","kind":"blank","prompt":"At 3 a.m. I ___ on the motorway when the engine stopped.","options":["was driving","drove","have driven"],"correct":0,"point":2},{"from":"int-5","kind":"blank","prompt":"The printer ___ in the middle of the meeting, so I sent the file by email.","options":["was breaking down","broke down","has broken down"],"correct":1,"point":2},{"from":"int-5","kind":"mcq","prompt":"Which sentence is the Result in a STAR story?","options":["I called the warehouse at once and asked for help.","Last May, our system crashed during a big sale.","In the end, the client renewed the contract."],"correct":2,"point":1},{"from":"int-4","kind":"mcq","prompt":"Which weakness is a good choice for a software tester?","options":["I don't notice small details, and I miss some bugs.","I find big meetings hard, so I prepare one point.","I'm a perfectionist, and I care a little too much."],"correct":1},{"from":"int-2","kind":"mcq","prompt":"The recruiter says: \"Could you tell me if you have a driving licence?\" Which answer is best?","options":["Yes, I could. I could tell you that.","Yes, I do. I have had it for ten years.","Yes, I am. I am a very good driver."],"correct":1},{"from":"int-1","kind":"mcq","prompt":"You check your introduction before an interview. What is the right test?","options":["Does it say why you dislike your current manager?","Does it say now, before and why this job, in order?","Does it list every job you have had since school?"],"correct":1}]},"explain":{"id":"c-int-5-e","course":"interview","unit":"int-5","type":"explain","level":"B1","title":{"en":"Your best stories","tr":"En iyi hikâyelerin","fa":"بهترین ماجراهایت"},"objective":{"en":"In this lesson you will learn to tell a short, true work story and build a bank of three stories.","tr":"Bu derste işinden kısa ve gerçek bir hikâye anlatmayı ve üç hikâyelik bir banka kurmayı öğreneceksin.","fa":"در این درس یاد می‌گیری یک ماجرای کوتاه و واقعی از کارت تعریف کنی و بانکی از سه ماجرا بسازی."},"hook":{"en":"\"Tell me about a time when...\" asks for one real day, not a summary of your career. They use what you did then to judge what you would do in this job. So tell one true story in four parts: STAR.","tr":"\"Tell me about a time when...\" kariyerinin özetini değil, gerçek bir günü ister. O gün ne yaptığına bakarak bu işte ne yapacağını değerlendirirler. Bu yüzden dört parçada gerçek bir hikâye anlat: STAR.","fa":"سؤال «Tell me about a time when...» یک روز واقعی را می‌خواهد، نه خلاصه‌ی سابقه‌ی کاری‌ات را. از کاری که آن روز کردی می‌سنجند در این شغل چه می‌کنی. پس یک ماجرای واقعی را در چهار بخش تعریف کن: STAR."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"STAR: one story, four parts","tr":"STAR: bir hikâye, dört parça","fa":"STAR: یک ماجرا، چهار بخش"},"steps":[{"en":"Situation and Task: say where, when and your job. This is background, so two sentences.","tr":"Situation ve Task: nerede, ne zaman ve işinin ne olduğunu söyle. Bu arka plandır, iki cümle yeter.","fa":"در بخش Situation و Task بگو کجا و چه زمانی بود و کارت چه بود. این فقط زمینه است، پس دو جمله کافی است.","ex":"Last May our system crashed, and I was on duty."},{"en":"Action: this is most of your answer. Say \"I\", because they are judging you, not your team.","tr":"Action: cevabının çoğu budur. \"I\" de, çünkü değerlendirdikleri kişi ekibin değil, sensin.","fa":"بخش Action بیشتر جوابت است. بگو «I»، چون می‌خواهند درباره‌ی تو تصمیم بگیرند، نه درباره‌ی تیمت.","ex":"I found the update, told the team and wrote to customers."},{"en":"Result: say how it ended, with a number, or what you learned. Otherwise it proves nothing.","tr":"Result: nasıl bittiğini bir sayıyla ya da ne öğrendiğini söyle. Bu olmadan hikâye hiçbir şey kanıtlamaz.","fa":"در بخش Result بگو ماجرا چطور تمام شد (با یک عدد) یا از آن چه یاد گرفتی. وگرنه ماجرا چیزی را ثابت نمی‌کند.","ex":"We lost under an hour of sales."},{"en":"Prepare three stories in advance: it is hard under stress, and each answers many questions.","tr":"Üç hikâyeyi önceden hazırla: stres altında zordur ve her biri birçok soruyu cevaplar.","fa":"سه ماجرا را از قبل آماده کن، چون ساختنشان زیر فشار سخت است. هر کدام هم به چند سؤال جواب می‌دهد.","ex":"The crash story: a problem, pressure, a mistake"}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Background and events: past continuous and past simple","tr":"Arka plan ve olaylar: past continuous ve past simple","fa":"زمینه و اتفاق: گذشته‌ی استمراری و گذشته‌ی ساده"},"steps":[{"en":"Background in progress: was / were + -ing.","tr":"Süren arka plan: was / were + -ing.","fa":"برای زمینه‌ای که در جریان بود was یا were را با فعل ing می‌آوری.","ex":"I was preparing the report..."},{"en":"The event that interrupts: when + past simple.","tr":"Araya giren olay: when + past simple.","fa":"اتفاقی که وسط کار پیش آمد با when و گذشته‌ی ساده می‌آید.","ex":"...when the system crashed."},{"en":"Your actions, step by step: past simple.","tr":"Yaptıkların, adım adım: past simple.","fa":"کارهایی را که قدم‌به‌قدم کردی با گذشته‌ی ساده بگو.","ex":"I called IT and phoned each client."}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Background: was / were + -ing","I was preparing the report..."],["The event: past simple","...when the system crashed."],["Your steps, one by one: past simple","I called IT and phoned each client."],["while + background","While I was waiting, I checked the numbers."]]},"tip":{"en":"Turkish '-iyordum / -dım' and Persian 'داشتم می‌رفتم / رفتم' make the same split, so the idea is familiar. The trap is the English form: was + -ing, not 'I was drive'.","tr":"Türkçedeki '-iyordum / -dım' ayrımı aynıdır, yani fikir tanıdık. Tuzak İngilizcedeki biçimdedir: was + -ing; 'I was drive' değil.","fa":"تمایز «داشتم می‌رفتم / رفتم» در فارسی هم هست، پس فکرش آشناست. تله در شکل فعل انگلیسی است: was + ‎-ing، نه «I was drive»."}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"They will ask what you did","tr":"Ne yaptığını soracaklar","fa":"می‌پرسند خودت چه کردی"},"body":{"en":"Good interviewers ask more about your answer: \"What exactly did you do?\" So tell only true stories. A story that ended badly is fine if you say what you changed afterwards. Keep each one under two minutes, so they have time to ask.","tr":"İyi mülakatçılar cevabın üzerine soru sorar: \"What exactly did you do?\" Bu yüzden yalnızca gerçek hikâyeler anlat. Kötü biten bir hikâye de olur, yeter ki sonra neyi değiştirdiğini söyle. Soru sormaya zaman kalsın diye her biri iki dakikadan kısa olsun.","fa":"مصاحبه‌کننده‌های خوب درباره‌ی جوابت باز هم می‌پرسند: «What exactly did you do?» پس فقط ماجراهای واقعی تعریف کن. ماجرایی که بد تمام شده هم اشکالی ندارد، به شرطی که بگویی بعدش چه چیزی را عوض کردی. هر ماجرا کمتر از دو دقیقه باشد تا برای سؤال‌هایشان وقت بماند."},"phrases":[{"phrase":"Last March, I was ... when...","meaning":{"en":"Sets the scene and the event.","tr":"Arka planı ve olayı verir.","fa":"فضا و اتفاق را مشخص می‌کند."}},{"phrase":"My job was to...","meaning":{"en":"Gives the T in STAR.","tr":"STAR'daki T'yi verir.","fa":"همان T در STAR را می‌گوید."}},{"phrase":"In the end...","meaning":{"en":"Opens the result.","tr":"Sonucu söylemeye başlar.","fa":"نتیجه را شروع می‌کند."}},{"phrase":"take responsibility","meaning":{"en":"To accept that something is your job or your fault.","tr":"sorumluluk almak.","fa":"مسئولیت را پذیرفتن"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Turn a summary into a story","tr":"Özeti hikâyeye çevir","fa":"خلاصه را به ماجرا تبدیل کن"},"item":"Weak: We had a lot of problems that month, and we all worked hard, so in the end it was okay. Your facts: last May the system crashed during a sale; you were on duty; you found the faulty update and told the team; under an hour of sales lost.","answer":"Last May our system crashed during a sale, and I was on duty. I found the faulty update and told the team. We lost under an hour of sales.","walk":[{"en":"Choose one day and one problem.","tr":"Bir gün ve bir sorun seç.","fa":"یک روز و یک مشکل انتخاب کن."},{"en":"Change \"we\" to \"I\" for what you did. That is what they judge.","tr":"Kendi yaptıkların için \"we\" yerine \"I\" de. Değerlendirdikleri kısım budur.","fa":"برای کاری که خودت کردی، «we» را به «I» تبدیل کن، چون همین را می‌سنجند."},{"en":"Replace \"okay\" with a real result, so they can see what your work changed.","tr":"\"Okay\" yerine gerçek bir sonuç koy; böylece çalışmanın neyi değiştirdiğini görebilirler.","fa":"به‌جای «okay» یک نتیجه‌ی واقعی بگذار تا ببینند کار تو چه چیزی را عوض کرد."}]},"quick":{"prompt":"Last May I ___ the evening shift when the system crashed.","options":["was working","worked","work"],"correct":0,"why":{"en":"was working: it was the background, already in progress when the crash happened.","tr":"was working: arka plandır, sistem çöktüğünde zaten devam ediyordu.","fa":"جواب was working است، چون این کار زمینه‌ی ماجراست و وقتی سیستم از کار افتاد در جریان بود."}},"remember":{"en":"Say \"we\" once to thank your team. Then say \"I\". You can now tell a true work story in four parts. Next, you build your bank of three stories.","tr":"Ekibine teşekkür etmek için bir kez \"we\" de. Sonra \"I\" de. Artık gerçek bir iş hikâyesini dört parçada anlatabilirsin. Sırada üç hikâyelik bankanı kurmak var.","fa":"یک بار برای تشکر از تیمت بگو «we». بعد بگو «I». حالا می‌توانی یک ماجرای واقعی از کارت را در چهار بخش تعریف کنی. در ادامه بانک ماجرای خودت را با سه ماجرا می‌سازی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"What happened first: the past perfect","tr":"Önce ne oldu: past perfect","fa":"اول چه اتفاقی افتاد: ماضی بعید"},"steps":[{"en":"The earlier of two past actions: had + past participle.","tr":"İki geçmiş eylemden önce olanı: had + üçüncü hâl.","fa":"از میان دو کار گذشته، برای کاری که زودتر بوده had و اسم مفعول می‌آوری.","ex":"I had already saved the file."},{"en":"The later action: past simple.","tr":"Sonraki eylem: past simple.","fa":"کار بعدی را با گذشته‌ی ساده می‌آوری.","ex":"By the time my manager called back..."},{"en":"Use it only when the order matters.","tr":"Bunu sadece sıra önemliyse kullan.","fa":"فقط وقتی ترتیب مهم است از آن استفاده کن.","ex":"I called the clients, then I told my manager."}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Earlier action: had + past participle","I had already saved the file."],["Later action: past simple","...by the time my manager called back."],["Question","What had you tried before you asked for help?"]]},"body":{"en":"B2: in your STAR story, add one sentence with had + past participle to show what you had already done.","tr":"B2: STAR hikâyene, zaten ne yapmış olduğunu gösteren had + üçüncü hâlli bir cümle ekle.","fa":"در مسیر B2: به ماجرای STAR خودت جمله‌ای با had و اسم مفعول اضافه کن تا نشان بدهی چه کاری را از قبل کرده بودی."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
